import { useEffect, useState } from 'react';
import { Smartphone, RefreshCw } from 'lucide-react';
import { sendToServer } from '../os/link';
import { os, useOs } from '../os/store';
import { timeAgo } from '../../common/format';
import { focusScope } from '../os/spatialNav';

function QrImage({ svg, className }: { svg: string; className?: string }) {
  // The SVG string is generated by our own server from a URL; it contains no script.
  return <div className={`qr ${className ?? ''}`} dangerouslySetInnerHTML={{ __html: svg }} />;
}

function useCountdown(expiresAt: number | undefined): number {
  const [left, setLeft] = useState(0);
  useEffect(() => {
    if (!expiresAt) return;
    const tick = () => setLeft(Math.max(0, Math.round((expiresAt - Date.now()) / 1000)));
    tick();
    const t = window.setInterval(tick, 1000);
    return () => clearInterval(t);
  }, [expiresAt]);
  return left;
}

/** Compact card on the home screen, shown until a phone is paired. */
export function PairCard() {
  const code = useOs((s) => s.link.pairCode);
  const status = useOs((s) => s.link.status);
  if (status !== 'online' || !code) return null;
  return (
    <div className="pair-card glass">
      <QrImage svg={code.qrSvg} />
      <div>
        <h3>Điều khiển bằng điện thoại</h3>
        <p>Quét mã QR bằng camera điện thoại, hoặc mở địa chỉ bên dưới và nhập mã:</p>
        <p className="small" style={{ marginTop: '0.4rem' }}>
          {code.baseUrl}
        </p>
        <div className="code">{code.code.replace(/(\d{3})(\d{3})/, '$1 $2')}</div>
      </div>
    </div>
  );
}

/** Full pairing overlay (blue key / tray button). */
export function PairingOverlay() {
  const code = useOs((s) => s.link.pairCode);
  const remotes = useOs((s) => s.link.remotes);
  const status = useOs((s) => s.link.status);
  const settings = useOs((s) => s.link.serverSettings);
  const left = useCountdown(code?.expiresAt);

  useEffect(() => {
    focusScope(document.querySelector('[data-pairing-panel]'));
  }, []);

  return (
    <>
      <div className="overlay-backdrop" onClick={() => os.get().setOverlay('none')} />
      <div className="pairing-panel" data-nav-scope data-nav-trap data-pairing-panel>
        <div>
          {code && status === 'online' ? (
            <QrImage svg={code.qrSvg} />
          ) : (
            <div className="qr" style={{ width: '20rem', height: '20rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <div className="spinner" />
            </div>
          )}
        </div>
        <div>
          <h2>Ghép nối điện thoại</h2>
          <ol className="pairing-steps">
            <li>Kết nối điện thoại vào cùng mạng Wi-Fi với TV.</li>
            <li>Mở camera và quét mã QR, sau đó mở liên kết hiện ra.</li>
            <li>
              {settings?.requireConfirm === false
                ? 'Điện thoại sẽ được ghép nối ngay khi quét mã.'
                : 'Xác nhận yêu cầu hiện trên TV, kiểm tra mã 4 số trùng với điện thoại.'}
            </li>
          </ol>
          {code && (
            <>
              <div className="muted">Hoặc mở địa chỉ sau trên điện thoại và nhập mã:</div>
              <div className="pair-url">{code.baseUrl}</div>
              <div className="pair-code-big">{code.code.replace(/(\d{3})(\d{3})/, '$1 $2')}</div>
              <div className="pair-expiry">Mã đổi sau {left} giây. Mỗi mã chỉ dùng được một lần.</div>
            </>
          )}
          <div className="btn-row" style={{ marginTop: '1rem' }}>
            <button className="btn" onClick={() => sendToServer({ t: 'tv.pair.create' })} data-nav-default>
              <RefreshCw /> Tạo mã mới
            </button>
            <button className="btn" onClick={() => os.get().setOverlay('none')}>
              Đóng
            </button>
          </div>
          <div className="remote-list">
            <div className="muted small" style={{ marginBottom: '0.4rem' }}>
              Thiết bị đã ghép nối ({remotes.length}/{settings?.maxRemotes ?? '-'})
            </div>
            {remotes.length === 0 && <div className="muted">Chưa có thiết bị nào.</div>}
            {remotes.map((r) => (
              <div className="remote-row" key={r.id}>
                <Smartphone />
                <span className="name">
                  <span className={`status-dot ${r.online ? 'on' : ''}`} />
                  {r.name}
                </span>
                <span className="muted small" style={{ marginRight: '1rem' }}>
                  {r.online ? 'Đang kết nối' : timeAgo(r.lastSeenAt)}
                </span>
                <button className="btn" onClick={() => sendToServer({ t: 'tv.remote.revoke', remoteId: r.id })}>
                  Gỡ
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

/** Confirmation dialog for an incoming pairing request. */
export function PairRequestDialog() {
  const req = useOs((s) => s.link.pairRequests[0]);
  const left = useCountdown(req?.expiresAt);

  useEffect(() => {
    if (!req) return;
    const t = setTimeout(() => focusScope(document.querySelector('[data-pair-dialog]')), 0);
    return () => clearTimeout(t);
  }, [req?.requestId]);

  if (!req) return null;
  const decide = (approve: boolean) => {
    sendToServer({ t: 'tv.pair.decide', requestId: req.requestId, approve });
    os.get().setLink({ pairRequests: os.get().link.pairRequests.filter((r) => r.requestId !== req.requestId) });
  };
  return (
    <>
      <div className="overlay-backdrop" />
      <div
        className="dialog"
        data-nav-scope
        data-nav-trap
        data-pair-dialog
        data-dialog-open
        onKeyDown={(e) => {
          if (e.key === 'Escape' || e.key === 'GoBack' || e.keyCode === 461) {
            e.preventDefault();
            decide(false);
          }
        }}
      >
        <h2>Cho phép điều khiển TV?</h2>
        <p>
          <strong>{req.name}</strong>
          {req.platform ? ` (${req.platform})` : ''} muốn điều khiển TV này. Địa chỉ: {req.ip}.
          {req.method === 'code' ? ' Thiết bị đã nhập mã ghép nối thủ công.' : ''}
        </p>
        <p style={{ marginTop: '0.6rem' }}>Chỉ cho phép nếu mã dưới đây trùng với mã trên điện thoại:</p>
        <div className="verify">{req.verifyCode}</div>
        <p className="small muted">Tự động từ chối sau {left} giây.</p>
        <div className="btn-row">
          <button className="btn" onClick={() => decide(false)}>
            Từ chối
          </button>
          <button className="btn primary" onClick={() => decide(true)} data-nav-default>
            Cho phép
          </button>
        </div>
      </div>
    </>
  );
}
